//! Raw bindings to the C ABI in `corr-cuda/include/corr_cuda.h`.
//!
//! This module is deliberately a thin mirror of the header: struct layouts are
//! spelled out by hand rather than generated by bindgen, so that an accidental
//! change on the CUDA side shows up as a loud `struct_size` mismatch at run time
//! instead of as a silently misread field.
//!
//! Everything here is `unsafe`. The safe wrapper lives in [`crate::gpu`].

#![allow(non_camel_case_types)]

use std::ffi::CStr;
use std::os::raw::{c_char, c_int, c_void};

/// Must match `CORR_ABI_VERSION` in the header.
pub const CORR_ABI_VERSION: u32 = 5;

/// Must match `CORR_MAX_DEVICES` in the header: the length of the fixed device
/// array inside `corr_config`.
pub const CORR_MAX_DEVICES: usize = 8;

#[repr(C)]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum corr_status {
    CORR_OK = 0,
    CORR_ERR_ARG = 1,
    CORR_ERR_ABI = 2,
    CORR_ERR_CUDA = 3,
    CORR_ERR_CUFFT = 4,
    CORR_ERR_STATE = 5,
    CORR_ERR_BUSY = 6,
    CORR_ERR_NOMEM = 7,
    CORR_ERR_NOT_IMPL = 8,
    CORR_ERR_INTERNAL = 9,
}

impl corr_status {
    pub fn is_ok(self) -> bool {
        self == corr_status::CORR_OK
    }

    pub fn name(self) -> &'static str {
        match self {
            corr_status::CORR_OK => "CORR_OK",
            corr_status::CORR_ERR_ARG => "CORR_ERR_ARG",
            corr_status::CORR_ERR_ABI => "CORR_ERR_ABI",
            corr_status::CORR_ERR_CUDA => "CORR_ERR_CUDA",
            corr_status::CORR_ERR_CUFFT => "CORR_ERR_CUFFT",
            corr_status::CORR_ERR_STATE => "CORR_ERR_STATE",
            corr_status::CORR_ERR_BUSY => "CORR_ERR_BUSY",
            corr_status::CORR_ERR_NOMEM => "CORR_ERR_NOMEM",
            corr_status::CORR_ERR_NOT_IMPL => "CORR_ERR_NOT_IMPL",
            corr_status::CORR_ERR_INTERNAL => "CORR_ERR_INTERNAL",
        }
    }
}

/// Mirror of `corr_config`. `Default` fills `abi_version` and `struct_size`
/// correctly, which is the point: forgetting `struct_size` is otherwise a very
/// easy way to get a confusing `CORR_ERR_ABI` from a correct-looking config.
#[repr(C)]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct corr_config {
    pub abi_version: u32,
    pub struct_size: u32,
    /// Used only when `n_devices == 0`, which is the single-device fallback.
    pub device_id: i32,
    pub n_station: i32,
    pub n_freq: i32,
    pub frames_per_slot: i32,
    pub chunk_frames: i32,
    pub block_slots: i32,
    pub rows_per_fetch: i32,
    /// ABI v3: how many entries of `devices` are used. 0 means "just device_id".
    pub n_devices: i32,
    pub devices: [i32; CORR_MAX_DEVICES],
    /// ABI v4: `CORR_SPLIT_*`.
    pub split_mode: i32,
}

/// Mirrors of the `CORR_SPLIT_*` constants: how the pair space is divided.
pub const CORR_SPLIT_BASELINE_RANGE: i32 = 0;
pub const CORR_SPLIT_PAIR_COVERING: i32 = 1;
/// Split by *frames*: every device holds every station, owns its share of the
/// slots, and the library adds the partial rows when they are fetched.
pub const CORR_SPLIT_TIME_SLICE: i32 = 2;

/// Mirror of `corr_device_stats`: cumulative traffic through one device.
#[repr(C)]
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub struct corr_device_stats {
    pub device_id: i32,
    pub bytes_h2d: u64,
    pub bytes_d2h: u64,
    pub transfers: u64,
    /// Nanoseconds this thread spent inside each call, cumulative.
    pub ns_accumulate: u64,
    pub ns_slot_free: u64,
    pub ns_row_end: u64,
    pub ns_rows_wait: u64,
    pub ns_fetch: u64,
}

/// Mirror of `corr_device_plan`: one device's share of the pair space.
#[repr(C)]
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub struct corr_device_plan {
    pub device_id: i32,
    pub n_station_resident: i32,
    pub first_baseline: i32,
    pub n_baseline: i32,
    /// 1 when its baselines are exactly the range [first_baseline, +n_baseline).
    pub contiguous: i32,
}

impl Default for corr_config {
    fn default() -> Self {
        corr_config {
            abi_version: CORR_ABI_VERSION,
            struct_size: std::mem::size_of::<corr_config>() as u32,
            device_id: 0,
            n_station: 1,
            n_freq: 4096,
            frames_per_slot: 256,
            chunk_frames: 256,
            block_slots: 3,
            rows_per_fetch: 1,
            n_devices: 0,
            devices: [0; CORR_MAX_DEVICES],
            split_mode: CORR_SPLIT_BASELINE_RANGE,
        }
    }
}

/// Mirror of `corr_staging`. `base` already points at this station's region, so
/// every offset below is relative to it and `total_bytes` is that region's
/// extent -- not the size of the whole pinned allocation.
#[repr(C)]
#[derive(Debug, Clone, Copy)]
pub struct corr_staging {
    pub base: *mut i8,
    pub frame_stride: usize,
    pub slot_stride: usize,
    pub total_bytes: usize,
}

extern "C" {
    pub fn corr_abi_banner() -> *const c_char;
    pub fn corr_last_error() -> *const c_char;

    pub fn corr_create(cfg: *const corr_config, out_ctx: *mut *mut c_void) -> corr_status;
    pub fn corr_destroy(ctx: *mut c_void) -> corr_status;

    pub fn corr_staging_info(
        ctx: *mut c_void,
        station: i32,
        out: *mut corr_staging,
    ) -> corr_status;

    pub fn corr_row_accumulate(ctx: *mut c_void, slot_seq: i64, frames: i32) -> corr_status;
    pub fn corr_row_slot_free(ctx: *mut c_void, slot_seq: i64) -> corr_status;
    pub fn corr_row_end(ctx: *mut c_void, frames: u64) -> corr_status;
    pub fn corr_rows_wait(ctx: *mut c_void) -> corr_status;
    pub fn corr_rows_pending(ctx: *mut c_void, out_pending: *mut i32) -> corr_status;
    pub fn corr_rows_fetch(
        ctx: *mut c_void,
        out: *mut c_void,
        out_bytes: usize,
        out_rows: *mut i32,
    ) -> corr_status;

    pub fn corr_n_baseline(n_station: c_int) -> c_int;

    pub fn corr_baseline_pairs(
        n_station: c_int,
        out_jk: *mut c_int,
        out_len: c_int,
    ) -> corr_status;

    /// ABI v3: how many devices the context actually runs on, -1 for NULL.
    pub fn corr_n_devices(ctx: *mut c_void) -> i32;
    pub fn corr_device_plan_get(
        ctx: *mut c_void,
        device_index: i32,
        out: *mut corr_device_plan,
    ) -> corr_status;
    pub fn corr_device_stations(
        ctx: *mut c_void,
        device_index: i32,
        out_stations: *mut i32,
        out_len: i32,
    ) -> corr_status;
    pub fn corr_device_baselines(
        ctx: *mut c_void,
        device_index: i32,
        out_baselines: *mut i32,
        out_len: i32,
    ) -> corr_status;
    pub fn corr_device_stats_get(
        ctx: *mut c_void,
        device_index: i32,
        out: *mut corr_device_stats,
    ) -> corr_status;
}

/// Read the library's version banner. Empty string if the library somehow
/// returns NULL, which would itself be an ABI violation worth not crashing on.
pub fn abi_banner() -> String {
    // SAFETY: the contract says the returned pointer is a static NUL-terminated
    // string valid for the life of the process.
    unsafe { cstr_to_string(corr_abi_banner()) }
}

/// The last error recorded on this thread by the C side.
pub fn last_error() -> String {
    // SAFETY: as above; corr_last_error never returns NULL.
    unsafe { cstr_to_string(corr_last_error()) }
}

unsafe fn cstr_to_string(p: *const c_char) -> String {
    if p.is_null() {
        return String::new();
    }
    CStr::from_ptr(p).to_string_lossy().into_owned()
}

// The C header is the contract, and it is mirrored here by hand. `struct_size` is
// checked at run time, which catches a mismatch only when a run happens; these
// assertions catch it at *compile* time, in both crates, on the machine being
// built. They are the cheapest possible guard against the failure mode that a
// hand-mirrored ABI invites: changing one side and shipping the other.
const _: () = {
    use std::mem::{align_of, offset_of, size_of};
    // 5 x u32 (version, struct_size, device_id, n_station, n_freq) + 3 x u32
    // (frames_per_slot, chunk_frames, block_slots) + 1 x u32 (split_mode) ...
    // expressed as offsets rather than a magic total so the failure names a field.
    assert!(offset_of!(corr_config, abi_version) == 0);
    assert!(offset_of!(corr_config, struct_size) == 4);
    assert!(align_of::<corr_config>() == 4 || align_of::<corr_config>() == 8);
    assert!(size_of::<corr_config>() % align_of::<corr_config>() == 0);
    // The one field whose offset the C side hard-codes in its own validation.
    assert!(offset_of!(corr_config, struct_size) + size_of::<u32>() <= size_of::<corr_config>());
    assert!(size_of::<corr_device_plan>() > 0);
    assert!(size_of::<corr_device_stats>() > 0);
};
